package com.ntd.csdl;
import com.ntd.csdl.entity.*;import com.ntd.csdl.repo.*;import com.ntd.csdl.service.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.util.*;
class IncidentCompletionTests{
 JdbcTemplate jdbc;IncidentService service;IncidentRepository repository;LandlordService landlords;TransactionTemplate tx;Incident incident;
 @BeforeEach void init(){var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1","sa","");jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));jdbc.execute("CREATE TABLE incidents(incident_id VARCHAR(20) PRIMARY KEY,status VARCHAR(50))");jdbc.execute("CREATE TABLE incident_resolutions(resolution_id VARCHAR(20) PRIMARY KEY,incident_id VARCHAR(20),is_completed BOOLEAN,resolution_date DATE)");jdbc.update("INSERT INTO incidents VALUES('SC1','PENDING')");jdbc.update("INSERT INTO incident_resolutions VALUES('XL1','SC1',false,null)");repository=mock(IncidentRepository.class);landlords=mock(LandlordService.class);incident=Incident.builder().incidentId("SC1").room(Room.builder().roomId("R1").build()).status("PENDING").build();when(repository.findById("SC1")).thenReturn(Optional.of(incident));when(repository.save(any(Incident.class))).thenAnswer(a->{Incident i=a.getArgument(0);jdbc.update("UPDATE incidents SET status=? WHERE incident_id=?",i.getStatus(),i.getIncidentId());return i;});service=new IncidentService(repository,mock(RoomRepository.class),landlords,jdbc);}
 @Test void completePersistsAndKeepsHistory(){tx.executeWithoutResult(t->service.complete("SC1","owner"));assertEquals("COMPLETED",jdbc.queryForObject("SELECT status FROM incidents WHERE incident_id='SC1'",String.class));assertTrue(jdbc.queryForObject("SELECT is_completed FROM incident_resolutions",Boolean.class));assertNotNull(jdbc.queryForObject("SELECT resolution_date FROM incident_resolutions",java.sql.Date.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM incidents",Integer.class));verify(landlords).requireOwner("owner","R1");verify(repository,never()).deleteById(anyString());}
 @Test void anotherOwnerCannotComplete(){doThrow(new ResponseStatusException(HttpStatus.FORBIDDEN)).when(landlords).requireOwner("other","R1");assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(t->service.complete("SC1","other")));assertEquals("PENDING",jdbc.queryForObject("SELECT status FROM incidents",String.class));assertFalse(jdbc.queryForObject("SELECT is_completed FROM incident_resolutions",Boolean.class));}
 @Test void repeatedCompletionIsSafe(){tx.executeWithoutResult(t->service.complete("SC1","owner"));tx.executeWithoutResult(t->service.complete("SC1","owner"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM incidents",Integer.class));}
}
